+
+        MappedActionFilter filter = new MappedActionFilter() {
+            @Override
+            public String actionName() {
+                return "dummyAction";
+            }
+
+            @Override
+            public int order() {
+                return 0;
+            }
+
+            @Override
+            public <Request extends ActionRequest, Response extends ActionResponse> void apply(
+                Task task,
+                String action,
+                Request request,
+                ActionListener<Response> listener,
